for(const [key,allowed,fallback] of [['character',['Blue','Red'],'Blue'],['difficulty',['Easy','Normal','Hard'],'Easy'],['controls',['normal','large'],'normal']]){let value;try{value=localStorage.getItem('pf-'+key);}catch{}u[key]=allowed.includes(value)?value:fallback;}
